"use client";

import { useEffect, useState } from "react";
import Image from "next/image";
import { useRouter } from "next/navigation";

/* ------------------ Banner ------------------ */

import img1 from "../../../public/assets/img/poster1.webp";
import img2 from "../../../public/assets/img/poster 2.webp";
import img3 from "../../../public/assets/img/poster 3.webp";
import img4 from "../../../public/assets/img/poster 4.webp";
import img5 from "../../../public/assets/img/poster 5.webp";
import img6 from "../../../public/assets/img/poster 6.webp";
import img7 from "../../../public/assets/img/poster 7.webp";
import img8 from "../../../public/assets/img/poster 8.webp";
import img9 from "../../../public/assets/img/poster 9.webp";

const banners = [
  img1,
  img2,
  img3,
  img4,
  img5,
  img6,
  img7,
  img8,
  img9,
];

export const BigBanner = () => {
  const router = useRouter();

  const [activeSlide, setActiveSlide] = useState(0);

  /* ------------------ Auto Slider ------------------ */

  useEffect(() => {
    const interval = setInterval(() => {
      setActiveSlide((prev) =>
        prev === banners.length - 1 ? 0 : prev + 1
      );
    }, 4000);

    return () => clearInterval(interval);
  }, []);

  /* ------------------ Slide Change ------------------ */

  const goToSlide = (index) => {
    setActiveSlide(index);
  };

  const getPreviousIndex = () => {
    return activeSlide === 0
      ? banners.length - 1
      : activeSlide - 1;
  };

  const getNextIndex = () => {
    return activeSlide === banners.length - 1
      ? 0
      : activeSlide + 1;
  };

  const previousIndex = getPreviousIndex();
  const nextIndex = getNextIndex();

  /* ------------------ Promotion Redirect ------------------ */

  const handlePromotionClick = () => {
    router.push("/promotions");
  };

  return (
    <div className="w-full overflow-hidden">

      {/* ================= BANNER SLIDER ================= */}

      <div className="relative flex w-full items-center justify-center overflow-hidden">

        {/* ================= LEFT SIDE IMAGE ================= */}

        <button
          type="button"
          onClick={() => goToSlide(previousIndex)}
          className="
            absolute
            left-0
            z-10
            h-[110px]
            w-[22%]
            overflow-hidden
            rounded-r-xl
            opacity-70
            transition-all
            duration-500
            hover:opacity-100
            md:h-[200px]
          "
        >
          <Image
            src={banners[previousIndex]}
            alt="Previous Banner"
            fill
            sizes="30vw"
            className="object-cover"
          />
        </button>


        {/* ================= RIGHT SIDE IMAGE ================= */}

        <button
          type="button"
          onClick={() => goToSlide(nextIndex)}
          className="
            absolute
            right-0
            z-10
            h-[110px]
            w-[22%]
            overflow-hidden
            rounded-l-xl
            opacity-70
            transition-all
            duration-500
            hover:opacity-100
            md:h-[200px]
          "
        >
          <Image
            src={banners[nextIndex]}
            alt="Next Banner"
            fill
            sizes="30vw"
            className="object-cover"
          />
        </button>


        {/* ================= MAIN BANNER ================= */}

        <button
          type="button"
          onClick={handlePromotionClick}
          className="
            relative
            z-20
            h-[140px]
            w-[78%]
            overflow-hidden
            rounded-xl
            shadow-xl
            transition-transform
            duration-500
            hover:scale-[1.01]
            md:h-[250px]
            md:w-[77%]
          "
        >
          <Image
            src={banners[activeSlide]}
            alt={`Promotion Banner ${activeSlide + 1}`}
            fill
            priority
            sizes="(max-width: 768px) 78vw, 77vw"
            className="object-cover"
          />
        </button>

      </div>


      {/* ================= INDICATORS ================= */}

      <div className="mt-3 flex items-center justify-center gap-2 md:mt-5">

        {banners.map((_, index) => (
          <button
            key={index}
            type="button"
            onClick={() => goToSlide(index)}
            aria-label={`Go to slide ${index + 1}`}
            className={`
              h-1.5
              rounded-full
              transition-all
              duration-300
              md:h-2
              ${
                activeSlide === index
                  ? "w-7 bg-[#00e5c3] md:w-9"
                  : "w-5 bg-white/60 hover:bg-white"
              }
            `}
          />
        ))}

      </div>

    </div>
  );
};